def transform(grid):
    h,w=len(grid),len(grid[0])
    counts={v:sum(row.count(v) for row in grid) for v in set(x for row in grid for x in row)}
    bg=max(counts,key=counts.get)
    pat=None
    for row in grid:
        i=0
        while i<w:
            if row[i]==bg: i+=1; continue
            j=i
            while j<w and row[j]!=bg: j+=1
            if j-i>1 and (pat is None or j-i>len(pat)): pat=row[i:j]
            i=j
    if pat is None: return [r[:] for r in grid]
    marker=next((v for v,n in counts.items() if v!=bg and v not in pat),None)
    out=[r[:] for r in grid]
    if marker is None: return out
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v==marker:
                for k,x in enumerate(pat):
                    j=c-2+k
                    if 0<=j<w: out[r][j]=x
    return out
